namespace InannaOctaquetra.Reading.Data;

/// <summary>
/// The three pictures the Octaquetra of Inanna ships, embedded in this assembly so every head -
/// desktop and Android alike - reads them the same way, with nothing to copy beside the app.
/// They are generated by Packaging/IconRenderer from the artwork in Packaging/Artwork.
/// </summary>
public static class ArtAssets
{
    private const string Prefix = "InannaOctaquetra.Reading.Art.";

    private static readonly Lazy<byte[]> _velvet = new(() => Read("velvet.jpg"));
    private static readonly Lazy<byte[]> _velvetPrint = new(() => Read("velvet-print.jpg"));
    private static readonly Lazy<byte[]> _inscribed = new(() => Read("octaquetra-inscribed.png"));

    /// <summary>Royal purple crushed velvet for the window background (2400x1500 JPEG).</summary>
    public static byte[] VelvetJpeg => _velvet.Value;

    /// <summary>The same velvet, toned for print, for the PDF report's bands (1800x1300 JPEG).</summary>
    public static byte[] VelvetPrintJpeg => _velvetPrint.Value;

    /// <summary>
    /// The gold band of the large Octaquetra behind the spread, engraved in cuneiform with Inana's
    /// claiming of the ME (2000x2000 PNG with transparency; see Packaging/Artwork/Tablet/SOURCES.md).
    /// </summary>
    public static byte[] InscribedOctaquetraPng => _inscribed.Value;

    //An unreadable resource is an empty array, never an exception: every caller has a drawn fallback
    private static byte[] Read(string name)
    {
        try
        {
            using var stream = typeof(ArtAssets).Assembly.GetManifestResourceStream(Prefix + name);
            if (stream == null) { return []; }
            using var copy = new MemoryStream();
            stream.CopyTo(copy);
            return copy.ToArray();
        }
        catch (Exception)
        {
            return [];
        }
    }
}
